// Philox-4x32-10 — the C15 sampler RNG contract (spec risk 2: reproducibility).
//
// LAW: the canonical Philox-4x32-10 (D.1 = 0xD2511F53, D.2 = 0xCD9E8D57,
// W = 0x9E3779B9, multiplier-high semantics h1 = mulh(a, b)). The
// authoritative implementation is the METAL one (kernels run in the hot
// path); Swift is the CPU-sampler port. They are pinned BIT-IDENTICAL by
// the golden fixture head_philox_golden.bin, generated by compiling the
import Foundation

public enum QWPhilox {
    public enum UniformVersion: UInt32, Sendable, Hashable {
        case legacyRounded32 = 1
        case upper24 = 2
    }

    static let d1: UInt32 = 0xD2511F53
    static let d2: UInt32 = 0xCD9E8D57
    static let w:  UInt32 = 0x9E3779B9

    /// hi(a·b) — the 64-bit product's high word.
    @inline(__always) static func mulh(_ a: UInt32, _ b: UInt32) -> UInt32 {
        UInt32((UInt64(a) &* UInt64(b)) >> 32)
    }
    @inline(__always) static func mullo(_ a: UInt32, _ b: UInt32) -> UInt32 {
        a &* b
    }

    /// 10-round Philox4x (counter ctr, key seed) → 4 u32 draws.
    public static func philox4(_ ctr: (UInt32, UInt32, UInt32, UInt32),
                               _ seed: UInt64) -> (UInt32, UInt32, UInt32, UInt32) {
        var k0 = UInt32(truncatingIfNeeded: seed >> 32), k1 = UInt32(truncatingIfNeeded: seed)
        var c = ctr
        for _ in 0..<10 {
            let h0 = (mulh(d1, c.0), mullo(d1, c.0))
            let h1 = (mulh(d2, c.2), mullo(d2, c.2))
            c = (h1.0 ^ c.1 ^ k0, h1.1, h0.0 ^ c.3 ^ k1, h0.1)
            k0 = k0 &+ d2
            k1 = k1 &+ d1
        }
        return c
    }

    /// Version 1 preserves fixtures but can round to 1. Version 2 uses
    /// equally spaced, exactly representable upper-24-bit values in [0,1).
    public static func uniform(_ word: UInt32, version: UniformVersion) -> Float {
        switch version {
        case .legacyRounded32: return Float(word) * (1.0 / 4294967296.0)
        case .upper24: return Float(word >> 8) * (1.0 / 16777216.0)
        }
    }

    public static func u(_ n: UInt64, seed: UInt64,
                         version: UniformVersion = .legacyRounded32) -> Float {
        let r = philox4((UInt32(truncatingIfNeeded: n), UInt32(truncatingIfNeeded: n >> 32), 0, 0), seed)
        return uniform(r.0, version: version)
    }
}
